package it.andreademartini.trading.backtest.reboundv2;

import it.andreademartini.trading.backtest.rebound.*;
import it.andreademartini.trading.backtest.patternv1.PatternV1Commission;
import it.andreademartini.trading.backtest.patternv2.*;
import it.andreademartini.trading.backtest.weeklytte.WeeklyTteStore;
import it.andreademartini.trading.marketdata.*;
import it.andreademartini.trading.risk.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import java.io.*;
import java.math.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static it.andreademartini.trading.backtest.reboundv2.TrendReboundV2Configuration.ExitMode.*;

class TrendReboundV2Test {
    @TempDir Path temp;
    static LocalDate day(int i){var d=LocalDate.of(2024,1,2);for(int n=0;n<i;n++)d=TrendReboundEngine.nextSession(d);return d;}
    static TrendReboundV2Configuration config(Object... changes){ObjectNode n=TrendReboundStore.JSON.valueToTree(TrendReboundV2Configuration.defaults());n.put("startDate",day(8).toString());n.put("endDate",day(17).toString());n.set("symbols",TrendReboundStore.JSON.valueToTree(List.of("TEST")));n.put("trendSmaPeriod",8);n.put("recoverySmaPeriod",3);n.put("atrPeriod",3);n.put("slippagePercentPerSide",0);n.set("commission",TrendReboundStore.JSON.valueToTree(PatternV1Commission.fixed(BigDecimal.ZERO)));n.set("splitCosts",TrendReboundStore.JSON.valueToTree(new PatternV2SplitCosts(List.of())));for(int i=0;i<changes.length;i+=2)n.set(changes[i].toString(),TrendReboundStore.JSON.valueToTree(changes[i+1]));return TrendReboundStore.JSON.convertValue(n,TrendReboundV2Configuration.class);}
    static HistoricalBar bar(int i,double open,double high,double low,double close){return new HistoricalBar("TEST",day(i).atTime(16,0),BigDecimal.valueOf(open),BigDecimal.valueOf(high),BigDecimal.valueOf(low),BigDecimal.valueOf(close),1000,BarInterval.DAILY,"TEST",PriceAdjustment.ADJUSTED);}
    static List<HistoricalBar> bars(){double[] prices={90,91,92,93,94,95,110,109,108,107,106,105,104,103,102,101,100,99};var rows=new ArrayList<HistoricalBar>();for(int i=0;i<prices.length;i++)rows.add(bar(i,prices[i]+.5,prices[i]+1,prices[i]-1,prices[i]));return rows;}
    static PositionSizingService sizing(){return new PositionSizingService(new TradePricingService());}
    static TrendReboundV2Run run(TrendReboundV2Configuration c,List<HistoricalBar> bars){var input=Map.of("TEST",bars);return new TrendReboundV2Engine(sizing()).simulate(c,input,PatternV2Dataset.capture(input).id(),null);}
    static TrendReboundRun baseline(TrendReboundV2Configuration c,List<HistoricalBar> bars){var input=Map.of("TEST",bars);return new TrendReboundEngine(sizing()).simulate(c.base(),input,PatternV2Dataset.capture(input).id(),WeeklyTteStore.hash(c.base()));}
    @Test void requestedDefaultsAreSeparateAndRecoveryIsOff(){var c=TrendReboundV2Configuration.defaults();assertEquals(14,c.atrPeriod());assertEquals(1.5,c.stopLossAtrMultiplier());assertEquals(1.5,c.takeProfitAtrMultiplier());assertEquals(ATR_TARGET_ONLY,c.exitMode());assertTrue(c.targetEnabled());assertFalse(c.recoveryEnabled());assertEquals(.5,c.riskPercent());assertEquals(30,c.maxOrderValuePercent());assertFalse(c.useLeverage());assertEquals(5,c.maxHoldingBars());}
    @Test void targetAndStopUseSignalAtrAndActualSlippedEntry(){var c=config("slippagePercentPerSide",.03);var r=run(c,bars());var t=r.portfolio().trades().getFirst();var a=r.tradeAudit().getFirst();assertEquals(t.entryExecutionPrice()-1.5*t.atrAtSignal(),a.initialStopLoss());assertEquals(t.entryExecutionPrice()+1.5*t.atrAtSignal(),a.rawTakeProfit());assertEquals(c.target("TEST",t.entryExecutionPrice(),t.atrAtSignal()),a.initialTakeProfit());assertEquals(103,c.target("TEST",100,2));assertEquals((a.initialTakeProfit()-t.entryExecutionPrice())/(t.entryExecutionPrice()-t.initialStop()),a.initialRewardRisk());}
    @Test void targetIsValidForTheConfiguredInstrumentTick(){var c=config("tickSizes",Map.of("TEST",new BigDecimal("0.05")));double value=c.target("TEST",100.013,2.007);assertEquals(0,BigDecimal.valueOf(value).remainder(new BigDecimal("0.05")).signum());assertTrue(value>=100.013+1.5*2.007);assertTrue(value-(100.013+1.5*2.007)<.05+1e-10);}
    @Test void atrHasNoLookAheadAndDoesNotMoveTargetAfterEntry(){var original=run(config(),bars());var modified=bars();modified.set(11,bar(11,107,130,104,120));var changed=run(config(),modified);assertEquals(original.portfolio().signals().getFirst().atr,changed.portfolio().signals().getFirst().atr);assertEquals(original.tradeAudit().getFirst().initialTakeProfit(),changed.tradeAudit().getFirst().initialTakeProfit());var t=changed.portfolio().trades().getFirst();assertEquals(changed.tradeAudit().getFirst().initialTakeProfit(),t.exitBasePrice());}
    @Test void intrabarTargetCanExecuteOnTheEntryBarAfterTheOpeningBuy(){var xs=bars();xs.set(10,bar(10,106.5,115,105,110));var r=run(config(),xs);var t=r.portfolio().trades().getFirst();var a=r.tradeAudit().getFirst();assertEquals("TAKE_PROFIT_ATR",t.exitReason());assertEquals(day(10),t.entryDate());assertEquals(t.entryDate(),t.exitDate());assertEquals(a.initialTakeProfit(),t.exitBasePrice());assertEquals(1,t.holdingBars());assertFalse(a.intrabarAmbiguous());}
    @Test void openingGapTargetWinsBeforeLaterLowCouldHitStop(){var xs=bars();xs.set(11,bar(11,115,116,90,110));var r=run(config(),xs);var t=r.portfolio().trades().getFirst();assertEquals("GAP_TARGET",t.exitReason());assertEquals(115,t.exitBasePrice());assertEquals(115,r.tradeAudit().getFirst().exitBarOpen());assertEquals("GAP_TARGET",r.tradeAudit().getFirst().gapExitType());assertFalse(r.tradeAudit().getFirst().intrabarAmbiguous());}
    @Test void openingGapStopIsNotFilledAtTheTheoreticalStop(){var xs=bars();xs.set(11,bar(11,90,120,89,110));var r=run(config(),xs);var t=r.portfolio().trades().getFirst();assertEquals("GAP_STOP",t.exitReason());assertEquals(90,t.exitBasePrice());assertFalse(r.tradeAudit().getFirst().intrabarAmbiguous());}
    @Test void entryBarWithBothExtremesUsesStopFirstAndRecordsAmbiguity(){var xs=bars();xs.set(10,bar(10,106.5,120,90,110));var r=run(config(),xs);var t=r.portfolio().trades().getFirst();assertEquals("STOP_LOSS",t.exitReason());assertEquals(t.initialStop(),t.exitBasePrice());assertTrue(r.tradeAudit().getFirst().intrabarAmbiguous());assertTrue(r.tradeAudit().getFirst().ambiguityReason().contains("STOP_FIRST"));}
    @Test void subsequentBarWithBothLevelsUsesStopFirst(){var xs=bars();xs.set(11,bar(11,107,120,90,110));var r=run(config(),xs);assertEquals("STOP_LOSS",r.portfolio().trades().getFirst().exitReason());assertTrue(r.tradeAudit().getFirst().intrabarAmbiguous());assertEquals(2,r.portfolio().trades().getFirst().holdingBars());}
    @Test void recoveryIsCompletelyDisabledInAtrModeEvenWhenProfitTargetIsOff(){var xs=bars();xs.set(10,bar(10,106.5,113,106,112));var r=run(config("takeProfitEnabled",false,"stopLossAtrMultiplier",5),xs);var t=r.portfolio().trades().getFirst();assertEquals("TIMEOUT",t.exitReason());assertNull(t.recoverySignalDate());assertNull(r.tradeAudit().getFirst().initialTakeProfit());assertFalse(r.tradeAudit().getFirst().recoveryEnabled());}
    @Test void recoveryOnlyReproducesEveryV1EconomicDecisionAndDoesNotUseTarget(){var xs=bars();xs.set(10,bar(10,106.5,120,106,112));xs.set(11,bar(11,111,112,90,105));var c=config("exitMode",RECOVERY_ONLY);var v1=baseline(c,xs);var v2=run(c,xs);assertEquals(TrendReboundV2Audit.economics(v1),TrendReboundV2Audit.economics(v2.portfolio()));assertEquals(v1.trades(),v2.portfolio().trades());assertEquals(v1.equity(),v2.portfolio().equity());assertEquals(true,v2.regressionAudit().get("recoveryOnlyMatchesV1"));assertEquals("PASS",v2.regressionAudit().get("status"));assertFalse(v2.tradeAudit().getFirst().takeProfitEnabled());assertNull(v2.tradeAudit().getFirst().initialTakeProfit());}
    @Test void firstOfBothTakesIntradayTargetBeforeARecoveryCloseSignal(){var xs=bars();xs.set(10,bar(10,106.5,120,106,112));var r=run(config("exitMode",FIRST_OF_BOTH),xs);assertEquals("TAKE_PROFIT_ATR",r.portfolio().trades().getFirst().exitReason());assertNull(r.portfolio().trades().getFirst().recoverySignalDate());}
    @Test void scheduledRecoveryOpenPrecedesAnIntradayTarget(){var xs=bars();xs.set(10,bar(10,106.5,109,106,108));xs.set(11,bar(11,109,120,105,112));var r=run(config("exitMode",FIRST_OF_BOTH),xs);var t=r.portfolio().trades().getFirst();assertEquals("RECOVERY",t.exitReason());assertEquals(day(10),t.recoverySignalDate());assertEquals(109,t.exitBasePrice());}
    @Test void targetGapAndRecoveryAtSameOpenHaveOneExecutionWithOpeningPrice(){var xs=bars();xs.set(10,bar(10,106.5,109,106,108));xs.set(11,bar(11,115,120,90,112));var r=run(config("exitMode",FIRST_OF_BOTH),xs);var t=r.portfolio().trades().getFirst();assertEquals("GAP_TARGET",t.exitReason());assertEquals(115,t.exitBasePrice());assertEquals(1,r.portfolio().trades().stream().filter(x->x.signalDate().equals(day(9))).count());}
    @Test void timeoutStillClosesOnTheFifthSessionIncludingEntryAsOne(){var r=run(config("stopLossAtrMultiplier",5,"takeProfitAtrMultiplier",100),bars());var t=r.portfolio().trades().getFirst();assertEquals("TIMEOUT",t.exitReason());assertEquals(5,t.holdingBars());assertEquals(day(14),t.exitDate());}
    @Test void sellSlippageAndCommissionsAreChargedExactlyOnce(){var xs=bars();xs.set(10,bar(10,106.5,115,105,110));var c=config("slippagePercentPerSide",.03,"commission",PatternV1Commission.ibkr());var r=run(c,xs);var t=r.portfolio().trades().getFirst();assertEquals(t.exitBasePrice()*(1-.0003),t.exitExecutionPrice(),1e-10);assertEquals(c.commission().charge(t.quantity(),BigDecimal.valueOf(t.entryExecutionPrice())).doubleValue(),t.entryCommission());assertEquals(c.commission().charge(t.quantity(),BigDecimal.valueOf(t.exitExecutionPrice())).doubleValue(),t.exitCommission());assertEquals((t.exitExecutionPrice()-t.entryExecutionPrice())*t.quantity()-t.entryCommission()-t.exitCommission(),t.netPnL(),1e-9);assertEquals(t.netPnL()+t.entryCommission()+t.exitCommission(),r.tradeAudit().getFirst().grossPnL(),1e-9);assertEquals(true,((Map<?,?>)r.portfolio().analysis().get("reconciliation")).get("passed"));}
    @Test void initialPositionSizingAndSignalUniverseRemainExactlyV1(){var c=config("slippagePercentPerSide",.03,"commission",PatternV1Commission.ibkr());var old=baseline(c,bars());var newer=run(c,bars()).portfolio();var a=old.trades().getFirst();var b=newer.trades().getFirst();assertEquals(a.quantity(),b.quantity());assertEquals(a.entryExecutionPrice(),b.entryExecutionPrice());assertEquals(a.initialRisk(),b.initialRisk());assertEquals(a.sizingRiskWithCosts(),b.sizingRiskWithCosts());assertEquals(old.signals().stream().map(s->s.symbol+":"+s.signalDate+":"+s.atr+":"+s.closes).toList(),newer.signals().stream().map(s->s.symbol+":"+s.signalDate+":"+s.atr+":"+s.closes).toList());}
    @Test void failedCapitalAndDatasetEndPreserveV1Semantics(){var rejected=run(config("initialCapital",1,"commission",PatternV1Commission.fixed(BigDecimal.ONE)),bars());assertTrue(rejected.portfolio().trades().isEmpty());assertTrue(rejected.portfolio().signals().stream().anyMatch(a->"INSUFFICIENT_CAPITAL_OR_RISK_BUDGET".equals(a.reason)));var end=run(config("endDate",day(10)),bars());assertNull(end.portfolio().trades().getFirst().exitDate());assertNull(end.tradeAudit().getFirst().netPnL());assertNotNull(end.tradeAudit().getFirst().initialTakeProfit());}
    @Test void separateHistoryReplayAndRealComparisonNeverWriteV1Files()throws Exception{
        var oldStore=new TrendReboundStore(temp.resolve("v1"));var newStore=new TrendReboundV2Store(temp.resolve("v2"));var snapshot=PatternV2Dataset.capture(Map.of("TEST",bars()));var original=baseline(config(),bars());oldStore.dataset(snapshot);oldStore.configuration(original.configuration());oldStore.save(original);byte[] before=Files.readAllBytes(temp.resolve("v1/current.json")),runBytes=Files.readAllBytes(temp.resolve("v1/runs/"+original.runId()+".json"));
        var service=new TrendReboundV2Service(newStore,new TrendReboundV2Engine(sizing()),oldStore);var runs=new ArrayList<TrendReboundV2Run>();for(var mode:List.of(RECOVERY_ONLY,ATR_TARGET_ONLY,FIRST_OF_BOTH))runs.add(service.fromV1(config("exitMode",mode),original.runId()));assertEquals(3,newStore.history().size());assertEquals(1,oldStore.history().size());assertArrayEquals(before,Files.readAllBytes(temp.resolve("v1/current.json")));assertArrayEquals(runBytes,Files.readAllBytes(temp.resolve("v1/runs/"+original.runId()+".json")));var replay=service.replay(runs.get(1).runId());assertEquals(runs.get(1).portfolio().trades(),replay.portfolio().trades());assertEquals(runs.get(1).tradeAudit(),replay.tradeAudit());assertEquals(3,((List<?>)service.compare(runs.stream().map(TrendReboundV2Run::runId).toList()).get("rows")).size());
        assertThrows(IllegalArgumentException.class,()->service.compare(List.of(runs.getFirst().runId())));
    }
    @Test void exportContainsV1SheetsTargetFieldsAnalysisAndOnlyExecutedModeRows()throws Exception{
        var c=config();var r=run(c,bars());try(var book=new XSSFWorkbook(new ByteArrayInputStream(new TrendReboundV2ExcelExporter().export(r)))){for(var sheet:List.of("DASHBOARD","CONFIGURATION","SIGNALS","TRADES","OPEN_POSITIONS","EQUITY","ANNUAL_RESULTS","RECONCILIATION","DATA_QUALITY","NOTES","EXIT_ANALYSIS","EXIT_MODE_COMPARISON","REGRESSION_AUDIT"))assertNotNull(book.getSheet(sheet));var headers=new HashSet<String>();book.getSheet("TRADES").getRow(0).forEach(cell->headers.add(cell.getStringCellValue()));assertTrue(headers.containsAll(List.of("Atr14AtSignal","InitialStopLoss","InitialTakeProfit","InitialRewardRisk","ExitMode","ExitBarOpen","GapExitType","GrossPnL","Commission","Slippage","NetPnL","NetR")));assertEquals(2,book.getSheet("EXIT_MODE_COMPARISON").getPhysicalNumberOfRows());assertEquals(7,book.getSheet("EXIT_ANALYSIS").getPhysicalNumberOfRows());}
    }
    @Test void incomparableRiskParametersOrDuplicateModesAreRejected(){var oldStore=new TrendReboundStore(temp.resolve("v1"));var store=new TrendReboundV2Store(temp.resolve("v2"));var service=new TrendReboundV2Service(store,new TrendReboundV2Engine(sizing()),oldStore);var snapshot=PatternV2Dataset.capture(Map.of("TEST",bars()));var a=service.onSnapshot(config(),snapshot);var b=service.onSnapshot(config("exitMode",RECOVERY_ONLY,"riskPercent",.6),snapshot);assertThrows(IllegalArgumentException.class,()->service.compare(List.of(a.runId(),b.runId())));var same=service.onSnapshot(config(),snapshot);assertThrows(IllegalArgumentException.class,()->service.compare(List.of(a.runId(),same.runId())));}
    @Test void leverageCannotChangeTheFrozenV1SizingModel(){assertThrows(IllegalArgumentException.class,()->config("useLeverage",true).validate());}
    @Test void signalAtr14AndTargetAreUnchangedWhenFutureBarsAreAppended(){var xs=new ArrayList<HistoricalBar>();for(int i=0;i<210;i++){double p=90+i*.1;xs.add(bar(i,p,p+1,p-1,p));}for(double p:new double[]{140,139,138,137,136,135,134}){int i=xs.size();xs.add(bar(i,p+.5,p+1,p-1,p));}var c=config("trendSmaPeriod",200,"recoverySmaPeriod",5,"atrPeriod",14,"startDate",day(200),"endDate",day(216));var full=run(c,xs);var prefix=run(config("trendSmaPeriod",200,"recoverySmaPeriod",5,"atrPeriod",14,"startDate",day(200),"endDate",day(214)),xs.subList(0,215));assertEquals(day(213),full.portfolio().signals().getFirst().signalDate);assertEquals(prefix.tradeAudit().getFirst().atr14AtSignal(),full.tradeAudit().getFirst().atr14AtSignal());assertEquals(prefix.tradeAudit().getFirst().initialTakeProfit(),full.tradeAudit().getFirst().initialTakeProfit());}
    @Test void quoteTickIsTranslatedIntoAdjustedShareBasisWithoutMovingTheStop(){var c=config();double target=c.target("TEST",25.013,1.007,BigDecimal.valueOf(4));var originalQuote=BigDecimal.valueOf(target).multiply(BigDecimal.valueOf(4));assertEquals(0,originalQuote.remainder(new BigDecimal(".01")).signum());assertTrue(target>=25.013+1.5*1.007);assertTrue(target-(25.013+1.5*1.007)<.0025+1e-10);}
    @Test void openingStopOnEntryIsChronologicallyKnownNotAnAmbiguousHighLowGuess(){var r=run(config("slippagePercentPerSide",8),bars());var t=r.portfolio().trades().getFirst();assertEquals(t.entryDate(),t.exitDate());assertEquals("GAP_STOP",t.exitReason());assertEquals(t.entryBasePrice(),t.exitBasePrice());assertFalse(r.tradeAudit().getFirst().intrabarAmbiguous());}
    @Test void alteredV1ReferenceIsRejectedRatherThanReportedAsParity(){var c=config("exitMode",RECOVERY_ONLY);var ref=baseline(c,bars());var curve=new ArrayList<>(ref.equity());var old=curve.getLast();curve.set(curve.size()-1,new TrendReboundRun.Equity(old.date(),old.equity()+1,old.cash(),old.notional(),old.exposurePercent(),old.drawdownPercent(),old.openPositions(),old.dataIncomplete()));var altered=new TrendReboundRun(ref.runId(),ref.strategy(),ref.strategyVersion(),ref.timestamp(),ref.configurationHash(),ref.datasetId(),ref.calendarVersion(),ref.configuration(),ref.signals(),ref.trades(),curve,ref.dataQuality(),ref.analysis(),ref.warnings());assertThrows(IllegalStateException.class,()->new TrendReboundV2Engine(sizing()).simulate(c,Map.of("TEST",bars()),ref.datasetId(),altered));}
    @Test void identicalPricesWithADifferentDatasetFingerprintCannotBeCompared(){var v1=new TrendReboundStore(temp.resolve("v1"));var store=new TrendReboundV2Store(temp.resolve("v2"));var service=new TrendReboundV2Service(store,new TrendReboundV2Engine(sizing()),v1);var first=service.onSnapshot(config(),PatternV2Dataset.capture(Map.of("TEST",bars())));var xs=bars();var b=xs.getFirst();xs.set(0,new HistoricalBar("TEST",b.dateTime(),b.getOpen(),b.getHigh(),b.getLow(),b.getClose(),2000,b.interval(),b.provider(),b.priceAdjustment()));var second=service.onSnapshot(config("exitMode",RECOVERY_ONLY),PatternV2Dataset.capture(Map.of("TEST",xs)));assertThrows(IllegalArgumentException.class,()->service.compare(List.of(first.runId(),second.runId())));}
    private static Map<String,List<HistoricalBar>> competing(boolean gap){var a=bars();a.set(11,bar(11,gap?115:107,120,104,110));var b=new ArrayList<HistoricalBar>();b.add(bar(0,89.5,90,88,89));for(int i=1;i<18;i++){var old=bars().get(i-1);b.add(bar(i,old.open(),old.high(),old.low(),old.close()));}var map=new TreeMap<String,List<HistoricalBar>>();map.put("AAA",a.stream().map(x->new HistoricalBar("AAA",x.dateTime(),x.getOpen(),x.getHigh(),x.getLow(),x.getClose(),x.volume(),x.interval(),x.provider(),x.priceAdjustment())).toList());map.put("BBB",b.stream().map(x->new HistoricalBar("BBB",x.dateTime(),x.getOpen(),x.getHigh(),x.getLow(),x.getClose(),x.volume(),x.interval(),x.provider(),x.priceAdjustment())).toList());return map;}
    @Test void intradayProfitCannotFundAnEarlierOpeningEntry(){var c=config("symbols",List.of("AAA","BBB"),"initialCapital",1000,"riskPercent",100,"maxOrderValuePercent",100);var input=competing(false);var r=new TrendReboundV2Engine(sizing()).simulate(c,input,PatternV2Dataset.capture(input).id(),null);var pending=r.portfolio().signals().stream().filter(s->s.symbol.equals("BBB")&&s.signalDate.equals(day(10))).findFirst().orElseThrow();assertEquals("INSUFFICIENT_CAPITAL_OR_RISK_BUDGET",pending.reason);assertEquals("TAKE_PROFIT_ATR",r.portfolio().trades().getFirst().exitReason());}
    @Test void openingTargetGapCanFinanceAnotherOpeningEntry(){var c=config("symbols",List.of("AAA","BBB"),"initialCapital",1000,"riskPercent",100,"maxOrderValuePercent",100);var input=competing(true);var r=new TrendReboundV2Engine(sizing()).simulate(c,input,PatternV2Dataset.capture(input).id(),null);assertEquals("GAP_TARGET",r.portfolio().trades().getFirst().exitReason());assertTrue(r.portfolio().trades().stream().anyMatch(t->t.symbol().equals("BBB")&&t.entryDate().equals(day(11))));}
}
